import React, { useState, useEffect, useRef } from 'react';
import axios from 'axios';

function App() {
  const [user, setUser] = useState(null);
  const [page, setPage] = useState('login');
  const [emailInput, setEmailInput] = useState('');
  const [data, setData] = useState([]);
  const [loading, setLoading] = useState(false);
  const [showForm, setShowForm] = useState(false);
  const [editingItem, setEditingItem] = useState(null);
  const [formData, setFormData] = useState({});
  const [courses, setCourses] = useState([]);
  const [enrolledCourseIds, setEnrolledCourseIds] = useState([]);
  const [selectedAssignment, setSelectedAssignment] = useState(null);
  const [submissionText, setSubmissionText] = useState('');
  const [showFileModal, setShowFileModal] = useState(false);
  const [currentSubmissionText, setCurrentSubmissionText] = useState('');
  const [currentSubmissionId, setCurrentSubmissionId] = useState(null);
  const [showGradeModal, setShowGradeModal] = useState(false);
  const [submissionToGrade, setSubmissionToGrade] = useState(null);
  const [gradeValue, setGradeValue] = useState('');
  const [feedbackText, setFeedbackText] = useState('');
  const [showConfirmDelete, setShowConfirmDelete] = useState(false);
  const [itemToDelete, setItemToDelete] = useState(null);
  const [deleteBase, setDeleteBase] = useState('');
  const [allUsers, setAllUsers] = useState([]);
  // AI Chat
  const [showChat, setShowChat] = useState(false);
  const [chatMessages, setChatMessages] = useState([
    { sender: 'bot', text: "Hello! I'm your Student Portal assistant. Ask me anything about how to use the portal!" }
  ]);
  const [chatInput, setChatInput] = useState('');
  const [chatLoading, setChatLoading] = useState(false);
  const chatEndRef = useRef(null);

  const API = 'http://localhost:5000/api';

  const getEndpoint = (pageName) => {
    if (pageName === 'courses') return 'courses';
    if (pageName === 'assignments') return 'assignments';
    if (pageName === 'announcements') return 'announcements';
    if (pageName === 'submissions') {
      return user?.role === 'student' ? `submissions?studentid=${user.id}` : 'submissions';
    }
    if (pageName === 'students') return 'users?role=student';
    if (pageName === 'instructors') return 'users?role=instructor'; // NEW: Admin manages instructors
    return null;
  };

  const getEmptyForm = (pageName) => {
    if (pageName === 'courses') return { title: '', description: '', syllabus: '' };
    if (pageName === 'assignments') return { title: '', duedate: '', description: '', courseid: '' };
    if (pageName === 'announcements') return { title: '', message: '', courseid: '' };
    if (pageName === 'students') return { name: '', email: '' };
    if (pageName === 'instructors') return { name: '', email: '', role: 'instructor', courseTitle: '', courseDescription: '', courseSyllabus: '' }; // NEW: Admin form with course fields
    return {};
  };

  const login = async (e) => {
    e.preventDefault();
    if (!emailInput.trim()) return alert('Please enter your email');
    try {
      const res = await axios.post(`${API}/users/login`, { email: emailInput.trim() });
      setUser(res.data);
      setPage(res.data.role === 'admin' ? 'instructors' : 'courses'); // NEW: Admin defaults to instructors page
    } catch (err) {
      alert('Login failed — user not found');
    }
  };

  // Reconstructed functions from logical structure (based on states and endpoints)
  useEffect(() => {
    if (user && page !== 'login') {
      loadData();
    }
  }, [page, user]);

  const loadData = async () => {
    setLoading(true);
    try {
      const endpoint = getEndpoint(page);
      if (endpoint) {
        let res;
        if (page === 'courses') {
          if (user.role === 'instructor') {
            res = await axios.get(`${API}/courses?instructorid=${user.id}`);
          } else {
            res = await axios.get(`${API}/courses`);
            // Set enrolled
            const enrolled = res.data.filter(course => course.students.includes(user.id)).map(course => course.id);
            setEnrolledCourseIds(enrolled);
          }
          setCourses(res.data);
        } else {
          res = await axios.get(`${API}/${endpoint}`);
        }
        setData(res ? res.data : []);
      }
    } catch (err) {
      alert('Error loading data');
    }
    setLoading(false);
  };

  const handleCreateOrUpdate = async () => {
    try {
      let res;
      const base = (page === 'students' || page === 'instructors') ? 'users' : getEndpoint(page).split('?')[0];
      if (editingItem) {
        res = await axios.put(`${API}/${base}/${editingItem.id}`, formData);
      } else {
        res = await axios.post(`${API}/${base}`, formData);
      }
      // NEW: For adding instructor, create tied course
      if (page === 'instructors' && !editingItem) {
        const instructorId = res.data.id;
        await axios.post(`${API}/courses`, {
          title: formData.courseTitle,
          description: formData.courseDescription,
          syllabus: formData.courseSyllabus,
          instructorid: instructorId
        });
      }
      setShowForm(false);
      loadData();
    } catch (err) {
      alert('Error saving');
    }
  };

  const editItem = (item) => {
    setEditingItem(item);
    setFormData(item);
    setShowForm(true);
  };

  const handleDelete = async () => {
    try {
      const base = (page === 'students' || page === 'instructors') ? 'users' : getEndpoint(page).split('?')[0];
      await axios.delete(`${API}/${base}/${itemToDelete.id}`);
      setShowConfirmDelete(false);
      loadData();
    } catch (err) {
      alert('Error deleting');
    }
  };

  const enrollInCourse = async (courseId) => {
    try {
      await axios.post(`${API}/courses/${courseId}/enroll`, { studentid: user.id });
      loadData();
    } catch (err) {
      alert('Error enrolling');
    }
  };

  const dropCourse = async (courseId) => {
    try {
      await axios.post(`${API}/courses/${courseId}/drop`, { studentid: user.id });
      loadData();
    } catch (err) {
      alert('Error dropping');
    }
  };

  const submitAssignment = async () => {
    try {
      await axios.post(`${API}/submissions`, { assignmentid: selectedAssignment.id, studentid: user.id, fileurl: submissionText });
      setSubmissionText('');
      setSelectedAssignment(null);
      loadData();
    } catch (err) {
      alert('Error submitting');
    }
  };

  const gradeSubmission = async () => {
    try {
      await axios.put(`${API}/submissions/${submissionToGrade.id}/grade`, { grade: gradeValue, feedback: feedbackText });
      setShowGradeModal(false);
      loadData();
    } catch (err) {
      alert('Error grading');
    }
  };

  const sendChatMessage = async () => {
    if (!chatInput.trim()) return;
    setChatMessages([...chatMessages, { sender: 'user', text: chatInput }]);
    setChatLoading(true);
    try {
      const res = await axios.post(`${API}/chat`, { message: chatInput });
      setChatMessages(prev => [...prev, { sender: 'bot', text: res.data.reply }]);
    } catch (err) {
      setChatMessages(prev => [...prev, { sender: 'bot', text: 'Sorry, error responding.' }]);
    }
    setChatLoading(false);
    setChatInput('');
    chatEndRef.current.scrollIntoView({ behavior: 'smooth' });
  };

  // Render
  if (loading) return <div>Loading...</div>;

  return (
    <div className="app">
      {page === 'login' ? (
        <form onSubmit={login}>
          <h1>Student Portal Login</h1>
          <input type="email" value={emailInput} onChange={(e) => setEmailInput(e.target.value)} placeholder="Enter your email" />
          <button type="submit">Login</button>
        </form>
      ) : (
        <>
          <div className="container">
            <h1>Welcome, {user.name} ({user.role})</h1>
            <nav>
              {user.role === 'student' && (
                <>
                  <button onClick={() => setPage('courses')}>Courses</button>
                  <button onClick={() => setPage('assignments')}>Assignments</button>
                  <button onClick={() => setPage('submissions')}>Submissions</button>
                  <button onClick={() => setPage('announcements')}>Announcements</button>
                </>
              )}
              {user.role === 'instructor' && (
                <>
                  <button onClick={() => setPage('courses')}>Courses</button>
                  <button onClick={() => setPage('assignments')}>Assignments</button>
                  <button onClick={() => setPage('submissions')}>Submissions</button>
                  <button onClick={() => setPage('announcements')}>Announcements</button>
                </>
              )}
              {user.role === 'admin' && (
                <>
                  <button onClick={() => setPage('instructors')}>Instructors</button>
                </>
              )}
            </nav>

            {page === 'courses' && (
              <>
                <h2>Courses</h2>
                {user.role === 'instructor' && <button onClick={() => { setShowForm(true); setEditingItem(null); setFormData(getEmptyForm(page)); }}>Add Course</button>}
                <table>
                  <thead>
                    <tr>
                      <th>Title</th>
                      <th>Description</th>
                      <th>Actions</th>
                    </tr>
                  </thead>
                  <tbody>
                    {data.map(course => (
                      <tr key={course.id}>
                        <td>{course.title}</td>
                        <td>{course.description}</td>
                        <td>
                          {user.role === 'student' && (
                            enrolledCourseIds.includes(course.id) ? (
                              <button onClick={() => dropCourse(course.id)}>Drop</button>
                            ) : (
                              <button onClick={() => enrollInCourse(course.id)}>Enroll</button>
                            )
                          )}
                          {user.role === 'instructor' && (
                            <>
                              <button onClick={() => editItem(course)}>Edit</button>
                              <button onClick={() => { setItemToDelete(course); setDeleteBase('courses'); setShowConfirmDelete(true); }}>Delete</button>
                            </>
                          )}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </>
            )}

            {page === 'assignments' && (
              <>
                <h2>Assignments</h2>
                {user.role === 'instructor' && <button onClick={() => { setShowForm(true); setEditingItem(null); setFormData(getEmptyForm(page)); }}>Add Assignment</button>}
                <table>
                  <thead>
                    <tr>
                      <th>Title</th>
                      <th>Due Date</th>
                      <th>Description</th>
                      <th>Actions</th>
                    </tr>
                  </thead>
                  <tbody>
                    {data.map(assignment => (
                      <tr key={assignment.id}>
                        <td>{assignment.title}</td>
                        <td>{assignment.duedate}</td>
                        <td>{assignment.description}</td>
                        <td>
                          {user.role === 'student' && <button onClick={() => setSelectedAssignment(assignment)}>Submit</button>}
                          {user.role === 'instructor' && (
                            <>
                              <button onClick={() => editItem(assignment)}>Edit</button>
                              <button onClick={() => { setItemToDelete(assignment); setDeleteBase('assignments'); setShowConfirmDelete(true); }}>Delete</button>
                            </>
                          )}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
                {selectedAssignment && (
                  <div>
                    <h3>Submit for {selectedAssignment.title}</h3>
                    <textarea value={submissionText} onChange={(e) => setSubmissionText(e.target.value)} placeholder="Submission text or URL" />
                    <button onClick={submitAssignment}>Submit</button>
                  </div>
                )}
              </>
            )}

            {page === 'submissions' && (
              <>
                <h2>{user.role === 'student' ? 'My Submissions' : 'Submissions'}</h2>
                <table>
                  <thead>
                    <tr>
                      <th>Assignment</th>
                      <th>Student</th>
                      <th>File</th>
                      <th>Grade</th>
                      <th>Feedback</th>
                      <th>Actions</th>
                    </tr>
                  </thead>
                  <tbody>
                    {data.map(sub => (
                      <tr key={sub.id}>
                        <td>{sub.assignmentid}</td>
                        <td>{sub.studentid}</td>
                        <td>{sub.fileurl}</td>
                        <td>{sub.grade}</td>
                        <td>{sub.feedback}</td>
                        <td>
                          {user.role === 'instructor' && <button onClick={() => { setSubmissionToGrade(sub); setShowGradeModal(true); }}>Grade</button>}
                          {user.role === 'student' && <button onClick={() => { setCurrentSubmissionId(sub.id); setCurrentSubmissionText(sub.fileurl); setShowFileModal(true); }}>Edit</button>}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </>
            )}

            {page === 'announcements' && (
              <>
                <h2>Announcements</h2>
                {user.role === 'instructor' && <button onClick={() => { setShowForm(true); setEditingItem(null); setFormData(getEmptyForm(page)); }}>Add Announcement</button>}
                <table>
                  <thead>
                    <tr>
                      <th>Title</th>
                      <th>Message</th>
                      <th>Date</th>
                      <th>Actions</th>
                    </tr>
                  </thead>
                  <tbody>
                    {data.map(ann => (
                      <tr key={ann.id}>
                        <td>{ann.title}</td>
                        <td>{ann.message}</td>
                        <td>{ann.dateposted}</td>
                        <td>
                          {user.role === 'instructor' && (
                            <>
                              <button onClick={() => editItem(ann)}>Edit</button>
                              <button onClick={() => { setItemToDelete(ann); setDeleteBase('announcements'); setShowConfirmDelete(true); }}>Delete</button>
                            </>
                          )}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </>
            )}

            {page === 'instructors' && (
              <>
                <h2>Manage Instructors</h2>
                <button onClick={() => { setShowForm(true); setEditingItem(null); setFormData(getEmptyForm(page)); }}>Add Instructor</button>
                <table>
                  <thead>
                    <tr>
                      <th>Name</th>
                      <th>Email</th>
                      <th>Actions</th>
                    </tr>
                  </thead>
                  <tbody>
                    {data.map(item => (
                      <tr key={item.id}>
                        <td>{item.name}</td>
                        <td>{item.email}</td>
                        <td>
                          <button onClick={() => { setEditingItem(item); setFormData({ name: item.name, email: item.email, role: 'instructor' }); setShowForm(true); }}>Edit</button>
                          <button onClick={() => { setItemToDelete(item); setDeleteBase('users'); setShowConfirmDelete(true); }}>Delete</button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </>
            )}

            {showForm && (
              <div style={{ position: 'fixed', top: 0, left: 0, width: '100%', height: '100%', background: 'rgba(0,0,0,0.5)', display: 'flex', justifyContent: 'center', alignItems: 'center', zIndex: 1000 }}>
                <div style={{ background: 'white', color: 'black', padding: '20px', borderRadius: '10px', width: '400px' }}>
                  <h3>{editingItem ? 'Edit' : 'Add'} {page.slice(0, -1)}</h3>
                  <input style={{ display: 'block', margin: '10px 0', width: '100%', padding: '10px' }} type="text" placeholder="Name/Title" value={formData.name || formData.title || ''} onChange={(e) => setFormData({ ...formData, [page === 'courses' || page === 'assignments' || page === 'announcements' ? 'title' : 'name']: e.target.value })} />
                  {(page === 'courses' || page === 'assignments' || page === 'announcements') && <textarea style={{ display: 'block', margin: '10px 0', width: '100%', padding: '10px' }} placeholder="Description/Message" value={formData.description || formData.message || ''} onChange={(e) => setFormData({ ...formData, [page === 'announcements' ? 'message' : 'description']: e.target.value })} />}
                  {page === 'assignments' && <input style={{ display: 'block', margin: '10px 0', width: '100%', padding: '10px' }} type="date" placeholder="Due Date" value={formData.duedate || ''} onChange={(e) => setFormData({ ...formData, duedate: e.target.value })} />}
                  {(page === 'assignments' || page === 'announcements') && <select style={{ display: 'block', margin: '10px 0', width: '100%', padding: '10px' }} value={formData.courseid || ''} onChange={(e) => setFormData({ ...formData, courseid: e.target.value })}>
                    <option value="">Select Course</option>
                    {courses.map(c => <option key={c.id} value={c.id}>{c.title}</option>)}
                  </select>}
                  {page === 'courses' && <textarea style={{ display: 'block', margin: '10px 0', width: '100%', padding: '10px' }} placeholder="Syllabus" value={formData.syllabus || ''} onChange={(e) => setFormData({ ...formData, syllabus: e.target.value })} />}
                  {(page === 'students' || page === 'instructors') && (
                    <>
                      <input style={{ display: 'block', margin: '10px 0', width: '100%', padding: '10px' }} type="email" placeholder="Email" value={formData.email || ''} onChange={(e) => setFormData({ ...formData, email: e.target.value })} />
                    </>
                  )}
                  {page === 'instructors' && !editingItem && (
                    <>
                      <input style={{ display: 'block', margin: '10px 0', width: '100%', padding: '10px' }} type="text" placeholder="Course Title" value={formData.courseTitle || ''} onChange={(e) => setFormData({ ...formData, courseTitle: e.target.value })} />
                      <textarea style={{ display: 'block', margin: '10px 0', width: '100%', padding: '10px' }} placeholder="Course Description" value={formData.courseDescription || ''} onChange={(e) => setFormData({ ...formData, courseDescription: e.target.value })} />
                      <textarea style={{ display: 'block', margin: '10px 0', width: '100%', padding: '10px' }} placeholder="Syllabus" value={formData.courseSyllabus || ''} onChange={(e) => setFormData({ ...formData, courseSyllabus: e.target.value })} />
                    </>
                  )}
                  <button style={{ margin: '10px 5px', padding: '10px' }} onClick={handleCreateOrUpdate}>{editingItem ? 'Update' : 'Create'}</button>
                  <button style={{ margin: '10px 5px', padding: '10px' }} onClick={() => setShowForm(false)}>Cancel</button>
                </div>
              </div>
            )}

            {showConfirmDelete && (
              <div style={{ position: 'fixed', top: 0, left: 0, width: '100%', height: '100%', background: 'rgba(0,0,0,0.5)', display: 'flex', justifyContent: 'center', alignItems: 'center' }}>
                <div style={{ background: 'white', color: 'black', padding: '20px', borderRadius: '10px' }}>
                  <h3>Confirm Delete?</h3>
                  <button onClick={handleDelete}>Yes</button>
                  <button onClick={() => setShowConfirmDelete(false)}>No</button>
                </div>
              </div>
            )}

            {showGradeModal && (
              <div style={{ position: 'fixed', top: 0, left: 0, width: '100%', height: '100%', background: 'rgba(0,0,0,0.5)', display: 'flex', justifyContent: 'center', alignItems: 'center' }}>
                <div style={{ background: 'white', color: 'black', padding: '20px', borderRadius: '10px' }}>
                  <h3>Grade Submission</h3>
                  <input type="number" value={gradeValue} onChange={(e) => setGradeValue(e.target.value)} placeholder="Grade" />
                  <textarea value={feedbackText} onChange={(e) => setFeedbackText(e.target.value)} placeholder="Feedback" />
                  <button onClick={gradeSubmission}>Save</button>
                  <button onClick={() => setShowGradeModal(false)}>Cancel</button>
                </div>
              </div>
            )}

            {showFileModal && (
              <div style={{ position: 'fixed', top: 0, left: 0, width: '100%', height: '100%', background: 'rgba(0,0,0,0.5)', display: 'flex', justifyContent: 'center', alignItems: 'center' }}>
                <div style={{ background: 'white', color: 'black', padding: '20px', borderRadius: '10px' }}>
                  <h3>Edit Submission</h3>
                  <textarea value={currentSubmissionText} onChange={(e) => setCurrentSubmissionText(e.target.value)} />
                  <button onClick={async () => {
                    await axios.put(`${API}/submissions/${currentSubmissionId}`, { fileurl: currentSubmissionText });
                    setShowFileModal(false);
                    loadData();
                  }}>Update</button>
                  <button onClick={() => setShowFileModal(false)}>Cancel</button>
                </div>
              </div>
            )}

            <button onClick={() => setShowChat(true)} style={{ position: 'fixed', bottom: '20px', right: '20px', padding: '10px 20px', background: '#667eea', color: 'white', borderRadius: '50px' }}>Chat Help</button>
          </div>

          {showChat && (
            <div style={{
              position: 'fixed',
              bottom: '80px',
              right: '20px',
              width: '350px',
              height: '500px',
              background: 'white',
              borderRadius: '16px',
              boxShadow: '0 20px 50px rgba(0,0,0,0.3)',
              display: 'flex',
              flexDirection: 'column',
              zIndex: 1000
            }}>
              <div style={{ padding: '16px', background: '#667eea', color: 'white', borderRadius: '16px 16px 0 0', fontWeight: '600', fontSize: '1.1rem', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                NM Portal Assistant
                <button onClick={() => setShowChat(false)} style={{ background: 'none', border: 'none', color: 'white', fontSize: '24px', cursor: 'pointer' }}>×</button>
              </div>
              <div style={{ flex: 1, padding: '16px', overflowY: 'auto', background: '#f8fafc' }}>
                {chatMessages.map((msg, i) => (
                  <div key={i} style={{ margin: '10px 0', textAlign: msg.sender === 'user' ? 'right' : 'left' }}>
                    <div style={{
                      display: 'inline-block',
                      maxWidth: '80%',
                      padding: '12px 16px',
                      borderRadius: '16px',
                      background: msg.sender === 'user' ? '#667eea' : '#e2e8f0',
                      color: msg.sender === 'user' ? 'white' : '#333'
                    }}>
                      {msg.text}
                    </div>
                  </div>
                ))}
                {chatLoading && <div style={{ textAlign: 'left' }}><div style={{ display: 'inline-block', padding: '12px 16px', background: '#e2e8f0', borderRadius: '16px' }}>Thinking...</div></div>}
                <div ref={chatEndRef} />
              </div>
              <div style={{ padding: '16px', borderTop: '1px solid #e2e8f0', display: 'flex' }}>
                <input
                  type="text"
                  value={chatInput}
                  onChange={(e) => setChatInput(e.target.value)}
                  onKeyPress={(e) => e.key === 'Enter' && sendChatMessage()}
                  placeholder="Ask about the portal..."
                  style={{ flex: 1, padding: '12px', borderRadius: '8px', border: '2px solid #e2e8f0', fontSize: '1rem' }}
                />
                <button
                  onClick={sendChatMessage}
                  disabled={chatLoading}
                  style={{ marginLeft: '10px', padding: '12px 20px', background: '#667eea', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer' }}
                >
                  Send
                </button>
              </div>
            </div>
          )}
        </>
      )}
      <footer style={{ textAlign: 'center', padding: '30px', color: 'white', background: 'rgba(0,0,0,0.3)', marginTop: '50px' }}>
        <h3 style={{ margin: '0 0 10px' }}>Student Portal © 2025</h3>
        <p style={{ margin: 0, opacity: 0.9 }}>Nikko Manuel - Marlon Chipa Learning Management System</p>
      </footer>
    </div>
  );
}

export default App;
